contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(IOracleProvider newOracle, bool callFromThis) public {
        address before = address(c.oracle());
        bool reverted;
        if (callFromThis) {
            try c.updateOracle(newOracle) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = true;
        }
        address after = address(c.oracle());
        if (!reverted) {
            assert(after == address(newOracle));
        } else {
            assert(after == before);
        }
    }
}

