contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address account, uint256 amount, bool doOpenMake) public {
        require(account != address(0), "account must not be zero");

        bool reverted;
        UFixed18 mBefore = c.maintenance(account);
        UFixed18 nBefore = c.maintenanceNext(account);

        if (doOpenMake) {
            try c.openMakeFor{value: 0}(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor{value: 0}(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (!reverted) {
            UFixed18 mAfter = c.maintenance(account);
            UFixed18 nAfter = c.maintenanceNext(account);
            assert(mAfter.lte(nAfter) || nAfter.lte(mAfter));
        } else {
            UFixed18 mAfter = c.maintenance(account);
            UFixed18 nAfter = c.maintenanceNext(account);
            assert(mAfter.eq(mBefore) && nAfter.eq(nBefore));
        }
    }

    receive() external payable {}
}

