        JumpRateUtilizationCurve memory afterCurve = c.utilizationCurve();

        assert(
            afterCurve.minRate == beforeCurve.minRate &&
            afterCurve.maxRate == beforeCurve.maxRate &&
            afterCurve.targetRate == beforeCurve.targetRate &&
            afterCurve.targetUtilization == beforeCurve.targetUtilization
        );
    }

    receive() external payable {}
}

